# Validate YAML with Node.js (already confirmed available via npm ecosystem)
node -e "
const fs = require('fs');
const raw = fs.readFileSync('.github/workflows/ci.yml', 'utf8');

// ── 1. Basic structural checks via regex/string ──────────────────────────────
const checks = [
  // Triggers
  [/push:/, 'push trigger'],
  [/pull_request:/, 'pull_request trigger'],
  [/branches:\s*\n\s+- main/, 'branch filter: main'],
  // Concurrency
  [/concurrency:/, 'concurrency block'],
  [/cancel-in-progress: true/, 'cancel-in-progress'],
  // lint-and-test job
  [/lint-and-test:/, 'lint-and-test job'],
  [/actions\/checkout@v4/, 'checkout action'],
  [/actions\/setup-node@v4/, 'setup-node action'],
  [/node-version: '20'/, 'Node 20'],
  [/cache: 'npm'/, 'npm cache'],
  [/npm ci/, 'npm ci install'],
  [/npm run lint/, 'eslint step'],
  [/npm test/, 'jest step'],
  [/CI: true/, 'CI env var'],
  // docker-build job
  [/docker-build:/, 'docker-build job'],
  [/needs: lint-and-test/, 'docker needs lint-and-test'],
  [/github\.ref == 'refs\/heads\/main'/, 'main-branch guard'],
  [/github\.event_name == 'push'/, 'push-event guard'],
  [/docker\/setup-buildx-action@v3/, 'buildx action'],
  [/docker\/metadata-action@v5/, 'metadata action'],
  [/docker\/build-push-action@v6/, 'build-push action'],
  [/push: false/, 'push disabled (build only)'],
  [/cache-from: type=gha/, 'GHA layer cache (from)'],
  [/cache-to: type=gha,mode=max/, 'GHA layer cache (to)'],
];

let passed = 0, failed = 0;
checks.forEach(([re, label]) => {
  if (re.test(raw)) { console.log('  ✓', label); passed++; }
  else              { console.error('  ✗ MISSING:', label); failed++; }
});
console.log('');
console.log(passed + '/' + (passed+failed), 'checks passed' + (failed ? ' — ' + failed + ' FAILED' : '.'));
process.exit(failed > 0 ? 1 : 0);
"

