node -e "
const fs = require('fs');

// ── .dockerignore checks ──────────────────────────────────────────────────
const di = fs.readFileSync('.dockerignore', 'utf8');
const diLines = di.split('\n').map(l => l.trim()).filter(l => l && !l.startsWith('#'));

const mustExclude = ['.env', '.env.*', '.env*.local', '*.env', 'node_modules/'];
mustExclude.forEach(pattern => {
  if (!diLines.includes(pattern))
    throw new Error('.dockerignore missing pattern: ' + pattern);
});
console.log('.dockerignore — all required exclusions present ✓');

// ── ci.yml structural checks (regex, no YAML parser needed) ──────────────
const yml = fs.readFileSync('.github/workflows/ci.yml', 'utf8');

const checks = [
  [/push:\s*\n\s+branches:\s*\n\s+- main/,     'push-to-main trigger'],
  [/pull_request:\s*\n\s+branches:\s*\n\s+- main/, 'pull_request trigger'],
  [/npm ci/,                                    'npm ci install'],
  [/npm run lint/,                              'eslint step'],
  [/npm test/,                                  'jest step'],
  [/needs:\s*\[lint,\s*test\]/,                 'docker needs lint+test'],
  [/github\.ref == 'refs\/heads\/main'/,        'docker main-branch guard'],
  [/github\.event_name == 'push'/,              'docker push-event guard'],
  [/actions\/checkout@v4/,                      'checkout action'],
  [/actions\/setup-node@v4/,                    'setup-node action'],
  [/docker\/build-push-action/,                 'docker build-push action'],
  [/concurrency:/,                              'concurrency block'],
  [/cancel-in-progress: true/,                  'cancel-in-progress'],
];

checks.forEach(([re, label]) => {
  if (!re.test(yml)) throw new Error('ci.yml missing: ' + label);
});
console.log('ci.yml — all structural checks passed ✓');
"

